impl Parser<'_> {
    /// Parses the input string into a SQL statement AST. The entire string must
    /// be parsed as a single statement, ending with an optional semicolon.
    pub fn parse(statement: &str) -> Result<ast::Statement> {
        let mut parser = Self::new(statement);
        let stmt = parser.parse_statement()?;
        parser.skip(ast::Token::Semicolon);
        if parser.lexer.peek().is_some() {
            return errinput!("unexpected tokens after statement");
        }
        Ok(stmt)
    }

    /// Parse the input string into a SQL expression AST. The entire string must
    /// be parsed as a single expression. Only used in tests.
    #[cfg(test)]
    pub fn parse_expr(expr: &str) -> Result<ast::Expression> {
        let mut parser = Self::new(expr);
        let expr = parser.parse_expression()?;
        if parser.lexer.peek().is_some() {
            return errinput!("unexpected tokens after expression");
        }
        Ok(expr)
    }

    /// Creates a new parser for the given raw SQL string.
    fn new(input: &str) -> Parser<'_> {
        Self {
            lexer: Lexer::new(input).peekable(),
        }
    }

    /// Fetches the next lexer token, or errors if none is found.
    fn next(&mut self) -> Result<Token> {
        self.lexer.next().ok_or_else(|| errinput!("unexpected end of input"))?.transpose()
    }

    /// Returns the next identifier, or errors if not found.
    fn next_ident(&mut self) -> Result<String> {
        match self.next()? {
            Token::Ident(s) => Ok(s),
            Token::Keyword(k) => Err(errinput!("expected identifier, got keyword {k}")),
            t => Err(errinput!("expected identifier, got {t}")),
        }
    }

    /// Returns the next lexer token if it satisfies the predicate.
    fn next_if(&mut self, predicate: impl Fn(&Token) -> bool) -> Option<Token> {
        self.lexer.next_if(|t| predicate(t).unwrap_or(false))
    }

    /// Passes the next lexer token through the closure, consuming it if the
    /// closure returns Some. Returns the result of the closure.
    fn next_if_map<T>(&mut self, f: impl Fn(&Token) -> Option<T>) -> Option<T> {
        self.lexer.next_if_map(f)
    }

    /// Returns the next keyword if there is one.
    fn next_if_keyword(&mut self) -> Option<Keyword> {
        self.lexer.next_if(|t| matches!(t, Token::Keyword(_))).and_then(|t| {
            if let Token::Keyword(k) = t { Some(*k) } else { None }
        })
    }

    /// Consumes the next lexer token if it is the given token, returning true.
    fn next_is(&mut self, token: Token) -> bool {
        self.lexer.next_if(|t| *t == token).is_some()
    }

    /// Consumes the next lexer token if it's the expected token, or errors.
    fn expect(&mut self, expect: Token) -> Result<()> {
        if self.next_is(expect.clone()) {
            Ok(())
        } else {
            Err(errinput!("expected {expect}, got {:?}", self.peek()?))
        }
    }

    /// Consumes the next lexer token if it is the given token. Equivalent to
    /// next_is(), but expresses intent better.
    fn skip(&mut self, token: Token) {
        self.next_is(token);
    }

    /// Peeks the next lexer token if any, but transposes it for convenience.
    fn peek(&mut self) -> Result<Option<&Token>> {
        Ok(self.lexer.peek())
    }

    /// Parses a SQL statement.
    fn parse_statement(&mut self) -> Result<ast::Statement> {
        match self.next_if_keyword() {
            Some(Keyword::Begin) => self.parse_begin(),
            Some(Keyword::Commit) => self.parse_commit(),
            Some(Keyword::Rollback) => self.parse_rollback(),
            Some(Keyword::Explain) => self.parse_explain(),
            Some(Keyword::Create) => self.parse_create_table(),
            Some(Keyword::Drop) => self.parse_drop_table(),
            Some(Keyword::Delete) => self.parse_delete(),
            Some(Keyword::Insert) => self.parse_insert(),
            Some(Keyword::Update) => self.parse_update(),
            Some(Keyword::Select) => self.parse_select(),
            Some(k) => Err(errinput!("unexpected keyword {k}")),
            None => Err(errinput!("expected SQL statement")),
        }
    }

    /// Parses a BEGIN statement.
    fn parse_begin(&mut self) -> Result<ast::Statement> {
        let read_only = self.next_if_keyword() == Some(Keyword::Read);
        if read_only {
            self.expect(Keyword::Write)?;
        }
        self.expect(Keyword::Transaction)?;
        let as_of = if self.next_if_keyword() == Some(Keyword::As) {
            self.expect(Keyword::Of)?;
            Some(self.parse_expression()?)
        } else {
            None
        };
        Ok(ast::Statement::Begin { read_only, as_of })
    }

    /// Parses a COMMIT statement.
    fn parse_commit(&mut self) -> Result<ast::Statement> {
        Ok(ast::Statement::Commit)
    }

    /// Parses a ROLLBACK statement.
    fn parse_rollback(&mut self) -> Result<ast::Statement> {
        Ok(ast::Statement::Rollback)
    }

    /// Parses an EXPLAIN statement.
    fn parse_explain(&mut self) -> Result<ast::Statement> {
        let stmt = Box::new(self.parse_statement()?);
        Ok(ast::Statement::Explain(stmt))
    }

    /// Parses a CREATE TABLE statement.
    fn parse_create_table(&mut self) -> Result<ast::Statement> {
        let name = self.next_ident()?;
        self.expect(ast::Token::OpenParen)?;
        let mut columns = Vec::new();
        loop {
            columns.push(self.parse_create_table_column()?);
            if !self.next_is(ast::Token::Comma) {
                break;
            }
        }
        self.expect(ast::Token::CloseParen)?;
        Ok(ast::Statement::CreateTable { name, columns })
    }

    /// Parses a CREATE TABLE column definition.
    fn parse_create_table_column(&mut self) -> Result<ast::Column> {
        let name = self.next_ident()?;
        let datatype = match self.next_if_keyword() {
            Some(Keyword::Boolean | Keyword::Bool) => DataType::Boolean,
            Some(Keyword::Integer | Keyword::Int) => DataType::Integer,
            Some(Keyword::Float | Keyword::Double) => DataType::Float,
            Some(Keyword::String | Keyword::Text | Keyword::Varchar) => DataType::String,
            Some(k) => return errinput!("unexpected datatype keyword {k}"),
            None => return errinput!("expected datatype"),
        };

        let mut primary_key = false;
        let mut nullable = None;
        let mut default = None;
        let mut unique = false;
        let mut index = false;
        let mut references = None;

        loop {
            match self.next_if_keyword() {
                Some(Keyword::Primary) => {
                    self.expect(Keyword::Key)?;
                    primary_key = true;
                }
                Some(Keyword::Not) => {
                    self.expect(Keyword::Null)?;
                    nullable = Some(false);
                }
                Some(Keyword::Null) => {
                    self.expect(Keyword::Null)?;
                    nullable = Some(true);
                }
                Some(Keyword::Default) => {
                    default = Some(self.parse_expression()?);
                }
                Some(Keyword::Unique) => unique = true,
                Some(Keyword::Index) => index = true,
                Some(Keyword::References) => {
                    references = Some(self.next_ident()?);
                }
                Some(k) => return errinput!("unexpected column attribute {k}"),
                None => break,
            }
        }

        Ok(ast::Column {
            name,
            datatype,
            primary_key,
            nullable,
            default,
            unique,
            index,
            references,
        })
    }

    /// Parses a DROP TABLE statement.
    fn parse_drop_table(&mut self) -> Result<ast::Statement> {
        let if_exists = self.next_if_keyword() == Some(Keyword::If);
        if if_exists {
            self.expect(Keyword::Exists)?;
        }
        let name = self.next_ident()?;
        Ok(ast::Statement::DropTable { name, if_exists })
    }

    /// Parses a DELETE statement.
    fn parse_delete(&mut self) -> Result<ast::Statement> {
        self.expect(Keyword::From)?;
        let table = self.next_ident()?;
        let r#where = if self.next_if_keyword() == Some(Keyword::Where) {
            Some(self.parse_expression()?)
        } else {
            None
        };
        Ok(ast::Statement::Delete { table, r#where })
    }

    /// Parses an INSERT statement.
    fn parse_insert(&mut self) -> Result<ast::Statement> {
        self.expect(Keyword::Into)?;
        let table = self.next_ident()?;
        let columns = if self.next_is(ast::Token::OpenParen) {
            self.skip(ast::Token::OpenParen);
            let mut cols = Vec::new();
            loop {
                cols.push(self.next_ident()?);
                if !self.next_is(ast::Token::Comma) {
                    break;
                }
            }
            self.expect(ast::Token::CloseParen)?;
            Some(cols)
        } else {
            None
        };

        self.expect(Keyword::Values)?;
        self.expect(ast::Token::OpenParen)?;
        let mut values = Vec::new();
        loop {
            let mut row = Vec::new();
            loop {
                row.push(self.parse_expression()?);
                if !self.next_is(ast::Token::Comma) {
                    break;
                }
            }
            values.push(row);
            if !self.next_is(ast::Token::Comma) {
                break;
            }
        }
        self.expect(ast::Token::CloseParen)?;

        Ok(ast::Statement::Insert { table, columns, values })
    }

    /// Parses an UPDATE statement.
    fn parse_update(&mut self) -> Result<ast::Statement> {
        let table = self.next_ident()?;
        self.expect(Keyword::Set)?;

        let mut set = BTreeMap::new();
        loop {
            let column = self.next_ident()?;
            self.expect(ast::Token::Equal)?;
            let value = if self.next_is(Keyword::Default.into()) {
                None
            } else {
                Some(self.parse_expression()?)
            };
            set.insert(column, value);
            if !self.next_is(ast::Token::Comma) {
                break;
            }
        }

        let r#where = if self.next_if_keyword() == Some(Keyword::Where) {
            Some(self.parse_expression()?)
        } else {
            None
        };

        Ok(ast::Statement::Update { table, set, r#where })
    }

    /// Parses a SELECT statement.
    fn parse_select(&mut self) -> Result<ast::Statement> {
        let select = self.parse_select_clause()?;
        let from = self.parse_from_clause()?;
        let r#where = self.parse_where_clause()?;
        let group_by = self.parse_group_by_clause()?;
        let having = self.parse_having_clause()?;
        let order_by = self.parse_order_by_clause()?;
        let offset = self.parse_offset_clause()?;
        let limit = self.parse_limit_clause()?;

        Ok(ast::Statement::Select {
            select,
            from,
            r#where,
            group_by,
            having,
            order_by,
            offset,
            limit,
        })
    }

    /// Parses a SELECT clause, if present.
    fn parse_select_clause(&mut self) -> Result<Vec<(ast::Expression, Option<String>)>> {
        let mut select = Vec::new();
        loop {
            let expr = self.parse_expression()?;
            let alias = if self.next_if_keyword() == Some(Keyword::As) {
                Some(self.next_ident()?)
            } else {
                None
            };
            select.push((expr, alias));
            if !self.next_is(ast::Token::Comma) {
                break;
            }
        }
        Ok(select)
    }

    /// Parses a FROM clause, if present.
    fn parse_from_clause(&mut self) -> Result<Vec<ast::From>> {
        if self.next_if_keyword() != Some(Keyword::From) {
            return Ok(Vec::new());
        }
        let mut from = Vec::new();
        loop {
            from.push(self.parse_from_table()?);
            if let Some(join_type) = self.parse_from_join()? {
                let right = self.parse_from_table()?;
                let predicate = if self.next_if_keyword() == Some(Keyword::On) {
                    Some(self.parse_expression()?)
                } else {
                    None
                };
                from.push(ast::From::Join {
                    left: Box::new(from.pop().unwrap()),
                    right: Box::new(right),
                    r#type: join_type,
                    predicate,
                });
            } else {
                break;
            }
        }
        Ok(from)
    }

    // Parses a FROM table.
    fn parse_from_table(&mut self) -> Result<ast::From> {
        let name = self.next_ident()?;
        let alias = if self.next_if_keyword() == Some(Keyword::As) {
            Some(self.next_ident()?)
        } else if let Some(Token::Ident(_)) = self.peek() {
            Some(self.next_ident()?)
        } else {
            None
        };
        Ok(ast::From::Table { name, alias })
    }

    // Parses a FROM JOIN type, if present.
    fn parse_from_join(&mut self) -> Result<Option<ast::JoinType>> {
        Ok(match self.next_if_keyword() {
            Some(Keyword::Join) => Some(ast::JoinType::Inner),
            Some(Keyword::Cross) => {
                self.expect(Keyword::Join)?;
                Some(ast::JoinType::Cross)
            }
            Some(Keyword::Inner) => {
                self.expect(Keyword::Join)?;
                Some(ast::JoinType::Inner)
            }
            Some(Keyword::Left) => {
                self.expect(Keyword::Join)?;
                Some(ast::JoinType::Left)
            }
            Some(Keyword::Right) => {
                self.expect(Keyword::Join)?;
                Some(ast::JoinType::Right)
            }
            Some(Keyword::Outer) => {
                self.expect(Keyword::Join)?;
                Err(errinput!("unexpected OUTER keyword"))
            }
            _ => None,
        })
    }

    /// Parses a WHERE clause, if present.
    fn parse_where_clause(&mut self) -> Result<Option<ast::Expression>> {
        if self.next_if_keyword() != Some(Keyword::Where) {
            return Ok(None);
        }
        Ok(Some(self.parse_expression()?))
    }

    /// Parses a GROUP BY clause, if present.
    fn parse_group_by_clause(&mut self) -> Result<Vec<ast::Expression>> {
        if self.next_if_keyword() != Some(Keyword::Group) {
            return Ok(Vec::new());
        }
        self.expect(Keyword::By)?;
        let mut group_by = Vec::new();
        loop {
            group_by.push(self.parse_expression()?);
            if !self.next_is(ast::Token::Comma) {
                break;
            }
        }
        Ok(group_by)
    }

    /// Parses a HAVING clause, if present.
    fn parse_having_clause(&mut self) -> Result<Option<ast::Expression>> {
        if self.next_if_keyword() != Some(Keyword::Having) {
            return Ok(None);
        }
        Ok(Some(self.parse_expression()?))
    }

    /// Parses an ORDER BY clause, if present.
    fn parse_order_by_clause(&mut self) -> Result<Vec<(ast::Expression, ast::Direction)>> {
        if self.next_if_keyword() != Some(Keyword::Order) {
            return Ok(Vec::new());
        }
        self.expect(Keyword::By)?;
        let mut order_by = Vec::new();
        loop {
            let expr = self.parse_expression()?;
            let direction = match self.next_if_keyword() {
                Some(Keyword::Asc) => ast::Direction::Ascending,
                Some(Keyword::Desc) => ast::Direction::Descending,
                _ => ast::Direction::Ascending,
            };
            order_by.push((expr, direction));
            if !self.next_is(ast::Token::Comma) {
                break;
            }
        }
        Ok(order_by)
    }

    /// Parses a LIMIT clause, if present.
    fn parse_limit_clause(&mut self) -> Result<Option<ast::Expression>> {
        if self.next_if_keyword() != Some(Keyword::Limit) {
            return Ok(None);
        }
        Ok(Some(self.parse_expression()?))
    }

    /// Parses an OFFSET clause, if present.
    fn parse_offset_clause(&mut self) -> Result<Option<ast::Expression>> {
        if self.next_if_keyword() != Some(Keyword::Offset) {
            return Ok(None);
        }
        Ok(Some(self.parse_expression()?))
    }

    /// Parses an expression using the precedence climbing algorithm.
    fn parse_expression(&mut self) -> Result<ast::Expression> {
        self.parse_expression_at(Precedence::MIN)
    }

    /// Parses an expression at the given minimum precedence.
    fn parse_expression_at(&mut self, min_precedence: Precedence) -> Result<ast::Expression> {
        // Parse prefix operator if present.
        let mut lhs = if let Some(op) = self.parse_prefix_operator_at(min_precedence) {
            let rhs = self.parse_expression_at(op.precedence() + op.associativity())?;
            op.into_expression(rhs)
        } else {
            self.parse_expression_atom()?
        };

        // Parse infix operators.
        loop {
            let min_precedence = min_precedence + match lhs {
                ast::Expression::Operator(ast::Operator::Not(_)) => Associativity::Right,
                _ => Associativity::Left,
            };

            if let Some(op) = self.parse_infix_operator_at(min_precedence) {
                let rhs = self.parse_expression_at(op.precedence() + op.associativity())?;
                lhs = op.into_expression(lhs, rhs);
            } else {
                break;
            }
        }

        // Parse postfix operators.
        if let Some(op) = self.parse_postfix_operator_at(min_precedence)? {
            lhs = op.into_expression(lhs);
        }

        Ok(lhs)
    }

    /// Parses an expression atom.
    fn parse_expression_atom(&mut self) -> Result<ast::Expression> {
        match self.next()? {
            Token::Asterisk => Ok(ast::Expression::All),
            Token::Ident(s) => Ok(ast::Expression::Column(None, s)),
            Token::Keyword(k) => match k {
                Keyword::True => Ok(ast::Expression::Literal(ast::Literal::Boolean(true))),
                Keyword::False => Ok(ast::Expression::Literal(ast::Literal::Boolean(false))),
                Keyword::Null => Ok(ast::Expression::Literal(ast::Literal::Null)),
                Keyword::Infinity => Ok(ast::Expression::Literal(ast::Literal::Float(f64::INFINITY))),
                Keyword::NaN => Ok(ast::Expression::Literal(ast::Literal::Float(f64::NAN))),
                Keyword::Select | Keyword::From | Keyword::Where | Keyword::Group |
                Keyword::Having | Keyword::Order | Keyword::Limit | Keyword::Offset |
                Keyword::Join | Keyword::On | Keyword::And | Keyword::Or | Keyword::Not |
                Keyword::Begin | Keyword::Commit | Keyword::Rollback | Keyword::Explain |
                Keyword::Create | Keyword::Drop | Keyword::Delete | Keyword::Insert |
                Keyword::Update | Keyword::Values | Keyword::Into | Keyword::Set |
                Keyword::As | Keyword::Asc | Keyword::Desc | Keyword::By | Keyword::If |
                Keyword::Index | Keyword::Inner | Keyword::Left | Keyword::Outer |
                Keyword::Primary | Keyword::Read | Keyword::References | Keyword::Right |
                Keyword::String | Keyword::Table | Keyword::Text | Keyword::Time |
                Keyword::Transaction | Keyword::Unique | Keyword::Varchar | Keyword::Write |
                Keyword::Default | Keyword::Double | Keyword::Integer | Keyword::Int |
                Keyword::Float | Keyword::Boolean | Keyword::Bool | Keyword::Cross |
                Keyword::Of | Keyword::Only => {
                    Err(errinput!("unexpected keyword {k} in expression"))
                }
            },
            Token::Number(s) => {
                if s.contains('.') || s.contains('e') || s.contains('E') {
                    Ok(ast::Expression::Literal(ast::Literal::Float(s.parse().unwrap())))
                } else {
                    Ok(ast::Expression::Literal(ast::Literal::Integer(s.parse().unwrap())))
                }
            }
            Token::String(s) => Ok(ast::Expression::Literal(ast::Literal::String(s))),
            Token::Minus => {
                let expr = self.parse_expression_at(PrefixOperator::Minus.precedence())?;
                Ok(ast::Expression::Operator(ast::Operator::Negate(expr.into())))
            }
            Token::Plus => {
                let expr = self.parse_expression_at(PrefixOperator::Plus.precedence())?;
                Ok(ast::Expression::Operator(ast::Operator::Identity(expr.into())))
            }
            Token::OpenParen => {
                let expr = self.parse_expression()?;
                self.expect(ast::Token::CloseParen)?;
                Ok(expr)
            }
            Token::Keyword(Keyword::Exists) => {
                self.expect(ast::Token::OpenParen)?;
                let stmt = self.parse_statement()?;
                self.expect(ast::Token::CloseParen)?;
                // EXISTS is handled by the planner, not the parser
                Ok(ast::Expression::Function("EXISTS".to_string(), vec![ast::Expression::All]))
            }
            Token::Period | Token::Equal | Token::NotEqual | Token::GreaterThan |
            Token::GreaterThanOrEqual | Token::LessThan | Token::LessThanOrEqual |
            Token::LessOrGreaterThan | Token::Plus | Token::Slash | Token::Caret |
            Token::Percent | Token::Exclamation | Token::Question | Token::Comma |
            Token::Semicolon | Token::CloseParen => {
                Err(errinput!("unexpected token {self:?} in expression"))
            }
        }
    }

    /// Parses a prefix operator, if there is one and its precedence is at least
    /// min_precedence.
    fn parse_prefix_operator_at(&mut self, min_precedence: Precedence) -> Option<PrefixOperator> {
        match self.peek()? {
            Token::Minus if min_precedence <= PrefixOperator::Minus.precedence() => {
                self.next();
                Some(PrefixOperator::Minus)
            }
            Token::Plus if min_precedence <= PrefixOperator::Plus.precedence() => {
                self.next();
                Some(PrefixOperator::Plus)
            }
            Token::Keyword(Keyword::Not) if min_precedence <= PrefixOperator::Not.precedence() => {
                self.next();
                Some(PrefixOperator::Not)
            }
            _ => None,
        }
    }

    /// Parses an infix operator, if there is one and its precedence is at least
    /// min_precedence.
    fn parse_infix_operator_at(&mut self, min_precedence: Precedence) -> Option<InfixOperator> {
        match self.peek()? {
            Token::Keyword(Keyword::And) if min_precedence <= InfixOperator::And.precedence() => {
                self.next();
                Some(InfixOperator::And)
            }
            Token::Keyword(Keyword::Or) if min_precedence <= InfixOperator::Or.precedence() => {
                self.next();
                Some(InfixOperator::Or)
            }
            Token::Equal if min_precedence <= InfixOperator::Equal.precedence() => {
                self.next();
                Some(InfixOperator::Equal)
            }
            Token::NotEqual if min_precedence <= InfixOperator::NotEqual.precedence() => {
                self.next();
                Some(InfixOperator::NotEqual)
            }
            Token::GreaterThan if min_precedence <= InfixOperator::GreaterThan.precedence() => {
                self.next();
                Some(InfixOperator::GreaterThan)
            }
            Token::GreaterThanOrEqual if min_precedence <= InfixOperator::GreaterThanOrEqual.precedence() => {
                self.next();
                Some(InfixOperator::GreaterThanOrEqual)
            }
            Token::LessThan if min_precedence <= InfixOperator::LessThan.precedence() => {
                self.next();
                Some(InfixOperator::LessThan)
            }
            Token::LessThanOrEqual if min_precedence <= InfixOperator::LessThanOrEqual.precedence() => {
                self.next();
                Some(InfixOperator::LessThanOrEqual)
            }
            Token::Plus if min_precedence <= InfixOperator::Add.precedence() => {
                self.next();
                Some(InfixOperator::Add)
            }
            Token::Minus if min_precedence <= InfixOperator::Subtract.precedence() => {
                self.next();
                Some(InfixOperator::Subtract)
            }
            Token::Asterisk if min_precedence <= InfixOperator::Multiply.precedence() => {
                self.next();
                Some(InfixOperator::Multiply)
            }
            Token::Slash if min_precedence <= InfixOperator::Divide.precedence() => {
                self.next();
                Some(InfixOperator::Divide)
            }
            Token::Caret if min_precedence <= InfixOperator::Exponentiate.precedence() => {
                self.next();
                Some(InfixOperator::Exponentiate)
            }
            Token::Percent if min_precedence <= InfixOperator::Remainder.precedence() => {
                self.next();
                Some(InfixOperator::Remainder)
            }
            Token::Keyword(Keyword::Like) if min_precedence <= InfixOperator::Like.precedence() => {
                self.next();
                Some(InfixOperator::Like)
            }
            _ => None,
        }
    }

    /// Parses a postfix operator, if there is one and its precedence is at
    /// least min_precedence.
    fn parse_postfix_operator_at(
        &mut self,
        min_precedence: Precedence,
    ) -> Result<Option<PostfixOperator>> {
        match self.peek()? {
            Token::Exclamation if min_precedence <= PostfixOperator::Factorial.precedence() => {
                self.next();
                Ok(Some(PostfixOperator::Factorial))
            }
            Token::Keyword(Keyword::Is) => {
                self.next();
                let neg = self.next_if_keyword() == Some(Keyword::Not);
                let value = match self.next_if_keyword() {
                    Some(Keyword::Null) => ast::Literal::Null,
                    Some(Keyword::Nan) => ast::Literal::Float(f64::NAN),
                    Some(k) => return Err(errinput!("expected NULL or NAN, got {k}")),
                    None => return Err(errinput!("expected NULL or NAN after IS")),
                };
                Ok(Some(if neg {
                    PostfixOperator::IsNot(value)
                } else {
                    PostfixOperator::Is(value)
                }))
            }
            _ => Ok(None),
        }
    }
}

